"use client";

import {

  clampStaggerInterval,

  MOTION_DEFAULTS,

} from "./clamp";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

import { shouldAnimateMotion } from "./motion-policy";

import { resolveTween, toMotionEase } from "./resolve-tween";

import { useMotionProfile } from "./use-motion-profile";

import { motion, useReducedMotion } from "motion/react";

import {

  createElement,

  type ElementType,

  type ReactNode,

} from "react";

import type { CubicBezier, TweenIntent } from "./profiles/types";

export type StaggerProps = {

  children: ReactNode;

  className?: string;

  as?: ElementType;

  interval?: number;

  delay?: number;

  amount?: number;

  once?: boolean;

};

export type StaggerItemProps = {

  children: ReactNode;

  className?: string;

  as?: ElementType;

  y?: number;

  intent?: TweenIntent;

  ease?: CubicBezier;

  duration?: number;

};

const containerVariants = (interval: number, delay: number) => ({

  hidden: {},

  show: {

    transition: {

      staggerChildren: interval,

      delayChildren: delay,

    },

  },

});

const itemVariants = (

  y: number,

  duration: number,

  ease: CubicBezier,

) => ({

  hidden: { opacity: 0, y },

  show: {

    opacity: 1,

    y: 0,

    transition: {

      duration,

      ease: toMotionEase(ease),

    },

  },

});

export function Stagger({

  children,

  className,

  as = "div",

  interval,

  delay = MOTION_DEFAULTS.staggerDelay,

  amount = MOTION_DEFAULTS.staggerAmount,

  once = MOTION_DEFAULTS.staggerOnce,

}: StaggerProps) {

  const reduce = useReducedMotion();

  const profile = useMotionProfile();

  const Tag = as as ElementType;

  if (!shouldAnimateMotion(reduce)) {

    return createElement(Tag, { className }, children);

  }

  const Component = motion.create(Tag);

  return (

    <Component

      className={cn(className)}

      initial="hidden"

      whileInView="show"

      viewport={{ once, amount }}

      variants={containerVariants(

        clampStaggerInterval(interval ?? profile.stagger.normal),

        delay,

      )}

    >

      {children}

    </Component>

  );

}

export function StaggerItem({

  children,

  className,

  as = "div",

  y = MOTION_DEFAULTS.staggerY,

  intent = "enter",

  ease,

  duration,

}: StaggerItemProps) {

  const reduce = useReducedMotion();

  const profile = useMotionProfile();

  const tween = resolveTween(profile, { intent, ease, duration });

  const Tag = as as ElementType;

  if (!shouldAnimateMotion(reduce)) {

    return createElement(Tag, { className }, children);

  }

  const Component = motion.create(Tag);

  return (

    <Component

      className={cn(className)}

      variants={itemVariants(y, tween.duration, tween.ease)}

    >

      {children}

    </Component>

  );

}

"use client";

import {

  clampStaggerInterval,

  MOTION_DEFAULTS,

} from "./clamp";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

import { shouldAnimateMotion } from "./motion-policy";

import {

  accessibleTextFromLines,

  splitTextParts,

} from "./text-split";

import { resolveTween, toMotionEase } from "./resolve-tween";

import { useMotionProfile } from "./use-motion-profile";

import { motion, useReducedMotion } from "motion/react";

import {

  createElement,

  type CSSProperties,

  type ElementType,

} from "react";

import type { CubicBezier, TweenIntent } from "./profiles/types";

export type TextRevealProps = {

  text: string;

  mode?: "words" | "lines";

  lines?: string[];

  className?: string;

  as?: ElementType;

  interval?: number;

  delay?: number;

  amount?: number;

  once?: boolean;

  intent?: TweenIntent;

  ease?: CubicBezier;

  duration?: number;

};

const visuallyHidden: CSSProperties = {

  position: "absolute",

  width: 1,

  height: 1,

  padding: 0,

  margin: -1,

  overflow: "hidden",

  clip: "rect(0, 0, 0, 0)",

  whiteSpace: "nowrap",

  borderWidth: 0,

};

const containerVariants = (interval: number, delay: number) => ({

  hidden: {},

  show: {

    transition: {

      staggerChildren: interval,

      delayChildren: delay,

    },

  },

});

const fragmentVariants = (duration: number, ease: CubicBezier) => ({

  hidden: { opacity: 0, y: 12 },

  show: {

    opacity: 1,

    y: 0,

    transition: {

      duration,

      ease: toMotionEase(ease),

    },

  },

});

export function TextReveal({

  text,

  mode = "words",

  lines,

  className,

  as = "p",

  interval,

  delay = MOTION_DEFAULTS.staggerDelay,

  amount = MOTION_DEFAULTS.staggerAmount,

  once = MOTION_DEFAULTS.staggerOnce,

  intent = "enter",

  ease,

  duration,

}: TextRevealProps) {

  const reduce = useReducedMotion();

  const profile = useMotionProfile();

  const tween = resolveTween(profile, { intent, ease, duration });

  const Tag = as as ElementType;

  const accessible = accessibleTextFromLines(text, lines ?? []);

  if (!shouldAnimateMotion(reduce)) {

    return createElement(

      Tag,

      { className, "data-text-reveal-text": "" },

      accessible,

    );

  }

  const variants = fragmentVariants(tween.duration, tween.ease);

  const lineItems = lines ?? [text];

  const fragments =

    mode === "lines"

      ? lineItems.map((line, index) => (

          <motion.span

            key={`line-${String(index)}`}

            className="inline-block"

            variants={variants}

          >

            {line}

            {index < lineItems.length - 1 ? " " : null}

          </motion.span>

        ))

      : splitTextParts(text).map((part, index) =>

          part.type === "space" ? (

            <span key={`space-${String(index)}`}>{part.value}</span>

          ) : (

            <motion.span

              key={`word-${String(index)}`}

              className="inline-block"

              variants={variants}

            >

              {part.value}

            </motion.span>

          ),

        );

  return createElement(

    Tag,

    { className: cn("relative", className) },

    <span data-text-reveal-text="" style={visuallyHidden}>

      {accessible}

    </span>,

    <motion.span

      data-text-reveal-visual=""

      aria-hidden="true"

      initial="hidden"

      whileInView="show"

      viewport={{ once, amount }}

      variants={containerVariants(

        clampStaggerInterval(interval ?? profile.stagger.normal),

        delay,

      )}

    >

      {fragments}

    </motion.span>,

  );

}

"use client";

import { MOTION_DEFAULTS, parallaxTravelPx } from "./clamp";
import { shouldEnableParallax } from "./motion-policy";
import {
  motion,
  useReducedMotion,
  useScroll,
  useTransform,
} from "motion/react";
import {
  useEffect,
  useRef,
  useState,
  type ElementType,
  type ReactNode,
} from "react";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

/**
 * Motion owns `transform` on this node. Do not tween the same element with GSAP
 * (ScrollTrigger or otherwise). Nested children may use a different engine only
 * if they do not animate transform or opacity on this wrapper.
 */
export type ParallaxProps = {
  children: ReactNode;
  className?: string;
  as?: ElementType;
  speed?: number;
  disableBelow?: number;
};

export function Parallax({
  children,
  className,
  as = "div",
  speed = MOTION_DEFAULTS.parallaxSpeed,
  disableBelow,
}: ParallaxProps) {
  const reduce = useReducedMotion();
  const Tag = as as ElementType;
  const Component = motion.create(Tag);
  const ref = useRef<HTMLElement | null>(null);
  const [viewportWidth, setViewportWidth] = useState<number | null>(
    disableBelow == null ? null : disableBelow,
  );

  useEffect(() => {
    if (disableBelow == null) {
      setViewportWidth(null);
      return;
    }
    const media = window.matchMedia(
      `(max-width: ${String(disableBelow - 1)}px)`,
    );
    const update = () => {
      setViewportWidth(media.matches ? disableBelow - 1 : disableBelow);
    };
    update();
    media.addEventListener("change", update);
    return () => {
      media.removeEventListener("change", update);
    };
  }, [disableBelow]);

  const enabled = shouldEnableParallax({
    reduce,
    viewportWidth,
    disableBelow,
  });
  const travel = enabled ? parallaxTravelPx(speed) : 0;
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "end start"],
  });
  const y = useTransform(scrollYProgress, [0, 1], [-travel, travel]);

  return (
    <Component ref={ref} className={cn(className)} style={{ y }}>
      {children}
    </Component>
  );
}

"use client";

import { shouldAnimateMotion } from "./motion-policy";
import { motion, useReducedMotion, useScroll } from "motion/react";
import type { RefObject } from "react";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

export type ScrollProgressAxis = "x" | "y";

export type ScrollProgressProps = {
  className?: string;
  axis?: ScrollProgressAxis;
  /**
   * @experimental Container-scoped progress. Prefer page scope.
   * Requires `containerRef` when set to `container`.
   */
  scope?: "page" | "container";
  /**
   * @experimental Scroll target when `scope` is `container`.
   */
  containerRef?: RefObject<HTMLElement | null>;
};

export function ScrollProgress({
  className,
  axis = "x",
  scope = "page",
  containerRef,
}: ScrollProgressProps) {
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll(
    scope === "container"
      ? {
          target: containerRef,
          offset: ["start start", "end end"],
        }
      : undefined,
  );
  const progress = scrollYProgress;
  const isVertical = axis === "y";
  const reduced = !shouldAnimateMotion(reduce);

  return (
    <motion.div
      className={cn(
        "pointer-events-none bg-accent",
        isVertical
          ? "fixed top-0 left-0 h-full w-0.5 origin-top"
          : "fixed top-0 left-0 h-0.5 w-full origin-left",
        "z-[var(--z-sticky)]",
        className,
      )}
      style={
        isVertical
          ? { scaleY: reduced ? 1 : progress }
          : { scaleX: reduced ? 1 : progress }
      }
    />
  );
}

"use client";

import { clampImageScale, MOTION_DEFAULTS } from "./clamp";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

import { shouldAnimateMotion } from "./motion-policy";

import { resolveTween, toMotionEase } from "./resolve-tween";

import { useMotionProfile } from "./use-motion-profile";

import { motion, useReducedMotion } from "motion/react";

import type { ReactNode } from "react";

import type { CubicBezier, TweenIntent } from "./profiles/types";

export type ImageRevealDirection = "up" | "down" | "left" | "right";

export type ImageRevealProps = {

  children: ReactNode;

  className?: string;

  direction?: ImageRevealDirection;

  scale?: number;

  amount?: number;

  once?: boolean;

  intent?: TweenIntent;

  ease?: CubicBezier;

  duration?: number;

};

function hiddenTransform(

  direction: ImageRevealDirection,

  scale: number,

): { opacity: number; x?: string; y?: string; scale: number } {

  switch (direction) {

    case "down":

      return { opacity: 1, y: "-24%", scale };

    case "left":

      return { opacity: 1, x: "24%", scale };

    case "right":

      return { opacity: 1, x: "-24%", scale };

    default:

      return { opacity: 1, y: "24%", scale };

  }

}

export function ImageReveal({

  children,

  className,

  direction = "up",

  scale = MOTION_DEFAULTS.imageScale,

  amount = MOTION_DEFAULTS.staggerAmount,

  once = MOTION_DEFAULTS.staggerOnce,

  intent = "settle",

  ease,

  duration,

}: ImageRevealProps) {

  const reduce = useReducedMotion();

  const profile = useMotionProfile();

  const tween = resolveTween(profile, { intent, ease, duration });

  const nextScale = clampImageScale(scale);

  if (!shouldAnimateMotion(reduce)) {

    return <div className={cn("overflow-hidden", className)}>{children}</div>;

  }

  return (

    <div className={cn("overflow-hidden", className)}>

      <motion.div

        initial={hiddenTransform(direction, nextScale)}

        whileInView={{ opacity: 1, x: 0, y: 0, scale: 1 }}

        viewport={{ once, amount }}

        transition={{

          duration: tween.duration,

          ease: toMotionEase(tween.ease),

        }}

      >

        {children}

      </motion.div>

    </div>

  );

}

"use client";

import "lenis/dist/lenis.css";
import { ReactLenis, type LenisRef } from "lenis/react";
import { useReducedMotion } from "motion/react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import {
  resolveSmoothScrollMode,
  shouldEnableLenis,
  shouldPreventLenis,
  SMOOTH_SCROLL_DEFAULTS,
  type SmoothScrollMode,
} from "./smooth-scroll-options";
import { attachGsapLenisSync } from "./smooth-scroll-sync";
import {
  SmoothScrollContext,
  type SmoothScrollApi,
} from "./use-smooth-scroll";

export type SmoothScrollProviderProps = {
  children: ReactNode;
  lerp?: number;
};

export function SmoothScrollProvider({
  children,
  lerp = SMOOTH_SCROLL_DEFAULTS.lerp,
}: SmoothScrollProviderProps) {
  const reduce = useReducedMotion();
  const [finePointer, setFinePointer] = useState(false);
  const lenisRef = useRef<LenisRef>(null);
  const mode: SmoothScrollMode = resolveSmoothScrollMode({
    reduce,
    finePointer,
  });
  const enableLenis = shouldEnableLenis(mode);

  useEffect(() => {
    const media = window.matchMedia(FINE_POINTER_QUERY);
    const update = () => {
      setFinePointer(media.matches);
    };
    update();
    media.addEventListener("change", update);
    return () => {
      media.removeEventListener("change", update);
    };
  }, []);

  useEffect(() => {
    document.documentElement.dataset.smoothScrollMode = mode;
    return () => {
      delete document.documentElement.dataset.smoothScrollMode;
    };
  }, [mode]);

  useEffect(() => {
    if (!enableLenis) {
      return;
    }
    return attachGsapLenisSync(() => lenisRef.current?.lenis ?? null);
  }, [enableLenis]);

  const api = useMemo<SmoothScrollApi>(() => {
    const lenis = enableLenis ? (lenisRef.current?.lenis ?? null) : null;
    return {
      lenis,
      mode,
      scrollTo: (target, options) => {
        const instance = lenisRef.current?.lenis;
        if (instance) {
          instance.scrollTo(target, options);
          return;
        }
        if (typeof window === "undefined") {
          return;
        }
        const behavior = options?.immediate ? "auto" : "smooth";
        if (typeof target === "number") {
          window.scrollTo({ top: target, behavior });
          return;
        }
        if (typeof target === "string") {
          if (target === "top" || target === "start") {
            window.scrollTo({ top: 0, behavior });
            return;
          }
          document.querySelector(target)?.scrollIntoView({
            behavior,
            block: "start",
          });
          return;
        }
        target.scrollIntoView({ behavior, block: "start" });
      },
      start: () => {
        lenisRef.current?.lenis?.start();
      },
      stop: () => {
        lenisRef.current?.lenis?.stop();
      },
      resize: () => {
        lenisRef.current?.lenis?.resize();
      },
    };
  }, [enableLenis, mode]);

  if (!enableLenis) {
    return (
      <SmoothScrollContext.Provider value={{ ...api, lenis: null, mode }}>
        {children}
      </SmoothScrollContext.Provider>
    );
  }

  return (
    <SmoothScrollContext.Provider value={api}>
      <ReactLenis
        root
        ref={lenisRef}
        options={{
          autoRaf: SMOOTH_SCROLL_DEFAULTS.autoRaf,
          lerp,
          anchors: SMOOTH_SCROLL_DEFAULTS.anchors,
          stopInertiaOnNavigate: SMOOTH_SCROLL_DEFAULTS.stopInertiaOnNavigate,
          syncTouch: SMOOTH_SCROLL_DEFAULTS.syncTouch,
          smoothWheel: SMOOTH_SCROLL_DEFAULTS.smoothWheel,
          respectReducedMotion: SMOOTH_SCROLL_DEFAULTS.respectReducedMotion,
          prevent: shouldPreventLenis,
        }}
      >
        {children}
      </ReactLenis>
    </SmoothScrollContext.Provider>
  );
}

"use client";

import type Lenis from "lenis";
import { createContext, useContext } from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import { getReducedMotionSnapshot } from "./reduced-motion";
import {
  resolveSmoothScrollMode,
  type SmoothScrollMode,
} from "./smooth-scroll-options";

export type SmoothScrollToTarget = number | string | HTMLElement;

export type SmoothScrollToOptions = {
  immediate?: boolean;
  offset?: number;
  lock?: boolean;
};

export type SmoothScrollApi = {
  lenis: Lenis | null;
  mode: SmoothScrollMode;
  scrollTo: (target: SmoothScrollToTarget, options?: SmoothScrollToOptions) => void;
  start: () => void;
  stop: () => void;
  resize: () => void;
};

export const SmoothScrollContext = createContext<SmoothScrollApi | null>(null);

function nativeScrollTo(
  target: SmoothScrollToTarget,
  options?: SmoothScrollToOptions,
) {
  if (typeof window === "undefined") {
    return;
  }
  const behavior = options?.immediate ? "auto" : "smooth";
  if (typeof target === "number") {
    window.scrollTo({ top: target, behavior });
    return;
  }
  if (typeof target === "string") {
    if (target === "top" || target === "start") {
      window.scrollTo({ top: 0, behavior });
      return;
    }
    const node = document.querySelector(target);
    node?.scrollIntoView({ behavior, block: "start" });
    return;
  }
  target.scrollIntoView({ behavior, block: "start" });
}

export const nativeSmoothScrollApi: SmoothScrollApi = {
  lenis: null,
  mode: "reduced-motion",
  scrollTo: nativeScrollTo,
  start: () => undefined,
  stop: () => undefined,
  resize: () => undefined,
};

/**
 * Control API for the app-level SmoothScrollProvider.
 * Outside the provider this returns native window scrolling (lenis is null).
 */
export function useSmoothScroll(): SmoothScrollApi {
  const value = useContext(SmoothScrollContext);
  if (value) {
    return value;
  }
  const reduce = getReducedMotionSnapshot();
  const finePointer =
    typeof window !== "undefined" &&
    window.matchMedia(FINE_POINTER_QUERY).matches;
  return {
    ...nativeSmoothScrollApi,
    mode: resolveSmoothScrollMode({ reduce, finePointer }),
  };
}

import { FINE_POINTER_QUERY } from "./motion-policy";

export type SmoothScrollMode = "smooth" | "native-touch" | "reduced-motion";

export type SmoothScrollOptions = {
  lerp: number;
  anchors: boolean;
  stopInertiaOnNavigate: boolean;
  syncTouch: boolean;
  smoothWheel: boolean;
  autoRaf: boolean;
  respectReducedMotion: boolean;
};

export const SMOOTH_SCROLL_DEFAULTS: SmoothScrollOptions = {
  lerp: 0.1,
  anchors: true,
  stopInertiaOnNavigate: true,
  syncTouch: false,
  smoothWheel: true,
  autoRaf: false,
  respectReducedMotion: true,
};

export const LENIS_PREVENT_SELECTOR =
  "[data-lenis-prevent], [data-radix-dialog-content], [role='dialog']";

export function resolveSmoothScrollMode(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
}): SmoothScrollMode {
  if (options.reduce) {
    return "reduced-motion";
  }
  if (!options.finePointer) {
    return "native-touch";
  }
  return "smooth";
}

export function shouldEnableLenis(mode: SmoothScrollMode): boolean {
  return mode === "smooth";
}

export function shouldPreventLenis(node: HTMLElement): boolean {
  return Boolean(node.closest(LENIS_PREVENT_SELECTOR));
}

export { FINE_POINTER_QUERY };

import type Lenis from "lenis";
import { gsap, registerGsap, ScrollTrigger } from "./gsap";

type SyncRecord = {
  ticker: (time: number) => void;
  onScroll: () => void;
  boundLenis: Lenis | null;
};

let active: SyncRecord | null = null;

export function getGsapLenisSyncCount(): number {
  return active ? 1 : 0;
}

export function attachGsapLenisSync(
  getLenis: () => Lenis | null | undefined,
): () => void {
  registerGsap();

  if (active) {
    detach(active);
  }

  const onScroll = () => {
    ScrollTrigger.update();
  };

  const record: SyncRecord = {
    ticker: (time: number) => {
      const lenis = getLenis();
      if (!lenis) {
        return;
      }
      if (record.boundLenis !== lenis) {
        record.boundLenis?.off("scroll", onScroll);
        lenis.on("scroll", onScroll);
        record.boundLenis = lenis;
      }
      lenis.raf(time * 1000);
    },
    onScroll,
    boundLenis: null,
  };

  gsap.ticker.add(record.ticker);
  gsap.ticker.lagSmoothing(0);
  active = record;

  return () => {
    detach(record);
  };
}

function detach(record: SyncRecord) {
  if (active !== record) {
    return;
  }
  gsap.ticker.remove(record.ticker);
  record.boundLenis?.off("scroll", record.onScroll);
  gsap.ticker.lagSmoothing(500, 33);
  active = null;
}

"use client";

import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

let registered = false;
const plugins = [ScrollTrigger, useGSAP, CustomEase];

export function registerGsap() {
  if (registered || typeof window === "undefined") {
    return;
  }
  gsap.registerPlugin(...plugins);
  registered = true;
}

export function reducedMotionMatchMedia() {
  return gsap.matchMedia();
}

export { CustomEase, gsap, ScrollTrigger, useGSAP };

export const MOTION_DEFAULTS = {
  staggerInterval: 0.08,
  staggerDelay: 0,
  staggerAmount: 0.3,
  staggerOnce: true,
  staggerY: 16,
  parallaxSpeed: 0.2,
  parallaxSpeedMin: 0,
  parallaxSpeedMax: 0.45,
  parallaxRangePx: 72,
  magneticStrength: 0.35,
  magneticStrengthMin: 0,
  magneticStrengthMax: 1,
  magneticMaxOffset: 16,
  magneticMaxOffsetMin: 0,
  magneticMaxOffsetMax: 32,
  imageScale: 1,
  imageScaleMin: 1,
  imageScaleMax: 1.08,
  imageRevealY: 24,
  ease: [0.16, 1, 0.3, 1] as const,
  duration: 0.55,
};

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function clampParallaxSpeed(speed: number): number {
  return clamp(
    speed,
    MOTION_DEFAULTS.parallaxSpeedMin,
    MOTION_DEFAULTS.parallaxSpeedMax,
  );
}

export function clampMagneticStrength(strength: number): number {
  return clamp(
    strength,
    MOTION_DEFAULTS.magneticStrengthMin,
    MOTION_DEFAULTS.magneticStrengthMax,
  );
}

export function clampMagneticOffset(offset: number): number {
  return clamp(
    offset,
    MOTION_DEFAULTS.magneticMaxOffsetMin,
    MOTION_DEFAULTS.magneticMaxOffsetMax,
  );
}

export function clampImageScale(scale: number): number {
  return clamp(
    scale,
    MOTION_DEFAULTS.imageScaleMin,
    MOTION_DEFAULTS.imageScaleMax,
  );
}

export function clampStaggerInterval(interval: number): number {
  return clamp(interval, 0, 1);
}

export function parallaxTravelPx(speed: number): number {
  return clampParallaxSpeed(speed) * MOTION_DEFAULTS.parallaxRangePx;
}

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}

export type TextPart = {
  type: "word" | "space";
  value: string;
};

export function splitTextParts(text: string): TextPart[] {
  return text
    .split(/(\s+)/)
    .filter((value) => value.length > 0)
    .map((value) => ({
      type: /^\s+$/.test(value) ? "space" : "word",
      value,
    }));
}

export function joinTextParts(parts: TextPart[]): string {
  return parts.map((part) => part.value).join("");
}

export function accessibleTextFromLines(
  text: string | undefined,
  lines: string[],
): string {
  if (text != null && text.length > 0) {
    return text;
  }
  return lines.join(" ");
}

